/**
 * Every storey of a generated house is reachable on foot, or the stair is refused with the measurement.
 *
 * Houses are generated by seed (packages/arch/test/support/house-gen.ts): 7-15 m wide, 5-9 m deep, two or three
 * storeys, a stair drawn anywhere on every storey (usually where none fits), with and without furniture. The
 * plan goes through create_building, which moves each stair that does not work to the nearest one that does; the
 * building check must then pass and the walkthrough bot must reach every room. A house where no stair fits is
 * reported ("stair does not work: ... nothing fits instead") and left alone: that is an honest refusal, not a bot
 * failure. The first sweep of 60 houses found 13 the bot could not walk or the check refused (a stair standing over
 * the stairwell below, on its landing, a lane too narrow between two stairwells, a door leaf swinging into a pocket
 * beside the balustrade, furniture and people on the walkway).
 *
 * `SWEEP_N` (default 12) houses from `SWEEP_FROM` (default 1), besides the pinned ones.
 */
import { applyArchOps, checkBuilding } from '@aether/arch';
import { createWorld } from '@aether/core';
import { ensureAssetCatalog } from '@aether/physics';
import { describe, expect, it } from 'vitest';
import { walkthrough } from '../src';
import { generateHouse } from '../../arch/test/support/house-gen';
import { planArch } from '../../agent/src/providers/mock/arch';

const FROM = Number(process.env['SWEEP_FROM'] ?? 1);
const N = Number(process.env['SWEEP_N'] ?? 12);

/** Seeds whose first draft broke each rule, so they are always in the sweep. */
const PINNED = [5, 13, 15, 23, 36, 37, 38, 60];

describe('generated houses: every storey reachable', () => {
  const seeds = [...new Set([...PINNED, ...Array.from({ length: N }, (_, k) => FROM + k)])];
  for (const furnish of [false, true]) {
    it(`${seeds.length} houses ${furnish ? 'furnished' : 'bare'}: the building check and the bot agree, or the stair is refused`, async () => {
      const bad: string[] = [];
      let refused = 0;
      for (const seed of seeds) {
        const h = generateHouse(seed, { furnish });
        const built = applyArchOps(createWorld(), [{ op: 'create_building', plan: h.plan }]);
        if (built.errors.length > 0) {
          bad.push(`${h.label}: ${built.errors.map((e) => e.message).join('; ')}`);
          continue;
        }
        if (built.lines.some((l) => l.startsWith('stair does not work'))) {
          refused++;
          continue;
        }
        await ensureAssetCatalog(built.target);
        const report = checkBuilding(built.target, 'house');
        if (!report.passed) {
          bad.push(`${h.label}: building check: ${report.issues.map((i) => i.message).join('; ')}`);
          continue;
        }
        const r = await walkthrough(built.target, { trace: false });
        if (r.status !== 'passed') bad.push(`${h.label}: bot: ${r.summary}`);
      }
      expect(bad, bad.join('\n')).toEqual([]);
      // Refusals stay the exception.
      expect(refused).toBeLessThanOrEqual(Math.ceil(seeds.length * 0.1));
    }, 900_000);
  }
});

describe('the offline planner house with people at home', () => {
  // People stood on the walkway at the foot of the stair and in the strip beside the flight: the bot found no way up.
  for (const text of ['a family of four in a two-storey house', 'a family of six in a two-storey house', 'a villa with a pool and a family of five']) {
    for (const at of [[0.2, 1.2], [0.4, 2.2], [3, 3]] as const) {
      it(`${text}, stair drawn at (${at[0]}, ${at[1]}): every room is walked`, async () => {
        const plan = (planArch(text, '')?.arch?.ops[0] as { plan: { levels: Array<{ stairs: unknown[] }> } }).plan;
        plan.levels[0]!.stairs = [{ at, heading: 'east', width: 1 }];
        const built = applyArchOps(createWorld(), [{ op: 'create_building', plan }]);
        expect(built.errors).toEqual([]);
        await ensureAssetCatalog(built.target);
        const r = await walkthrough(built.target, { trace: false });
        expect(r.status, r.summary).toBe('passed');
      }, 180_000);
    }
  }
});
